// ============================================================
// === PILZKRANKHEIT WÜRFELN ===================================
// ============================================================
// - würfelnden Akteur wie bei den Gaben erkennen
// - genau ein Akteur im Target
// - keine Besitzerrechte am Target erforderlich
// - Zähigkeit und Seelenkraft automatisch vom Ziel auslesen
// - zuerst sichtbarer, unverrechneter 1W20-Wurf
// - danach Berechnung: 1W20 + Pilzmodifikator - Widerstand
// - bei -7 oder weniger sichtbarer Wiederholungswurf
// - Karte im bewährten Gabenlayout
// - echter GM-Makrobutton im geheimen SL-Bereich
// - gespeichertes Ziel, keine erneute Target-Auswahl
// - keine Erfolgs- oder Misserfolgsanzeige
// - Effektanlage ausschließlich über Block 6
// - Effektname immer „Pilzkrankheit“
// - Effektbild immer grüner Pilz
// ============================================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";

    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden ||
        !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.ResolveTokenName ||
        !globalThis.DSK?.GMAnfrage?.Speichern ||
        !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen ||
        !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.ButtonStyle ||
        !globalThis.DSK?.GabenUI?.Details ||
        !globalThis.DSK?.GabenUI?.InitGMMakroButton ||
        !globalThis.DSK?.UI?.Box ||
        !globalThis.DSK?.UI?.List;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden ||
        !DSK_FW?.Token?.Finde ||
        !DSK_FW?.ResolveTokenName ||
        !DSK_FW?.GMAnfrage?.Speichern ||
        !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen ||
        !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.ButtonStyle ||
        !DSK_FW?.GabenUI?.Details ||
        !DSK_FW?.GabenUI?.InitGMMakroButton ||
        !DSK_FW?.UI?.Box ||
        !DSK_FW?.UI?.List
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    DSK_FW.GabenUI.InitGMMakroButton();

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++
    const EFFEKT_NAME = "Pilzkrankheit";
    const FLAG_KEY = "pendingPilzkrankheit";
    const PILZ_BILD = "icons/consumables/mushrooms/convex-green-brown.webp";
    const SYSTEM_BILD = "https://assets.forge-vtt.com/644fbc20a9e089e2ef894956/DSK/Allgemein/system-dsk-info2.webp";

    const vorzeichen = wert => Number(wert) >= 0 ? `+ ${Number(wert)}` : `− ${Math.abs(Number(wert))}`;

    const istAktiverGM = () => {
        const gms = game.users.filter(user => user.isGM && user.active)
            .sort((a, b) => String(a.id).localeCompare(String(b.id)));
        return Boolean(game.user.isGM && (!gms[0] || gms[0].id === game.user.id));
    };

    // +++ 3 - KARTENKOPF ++++++++++++++++++++++++++++++++++++++
    const kopf = titel => DSK_FW.UI.Box("dskbox1", `
        <p style="display:flex;gap:8px;align-items:center;margin:0;">
            <span style="white-space:nowrap;display:flex;align-items:center;gap:8px;">
                <img src="${SYSTEM_BILD}" style="width:28px;border:none;background:transparent;flex-shrink:0;">
                <b>Systeminformation</b>
            </span>
        </p>
        <hr style="margin:4px 0;border:0;border-top:1px solid #c9bca6;">
        <p style="font-weight:bold;margin-top:6px;margin-bottom:0;">${titel}</p>
    `);

    // +++ 4 - ZIELAKTEUR LADEN ++++++++++++++++++++++++++++++++
    const ladeZielActor = async daten => {
        if (!daten) return null;

        if (daten.targetTokenId) {
            const token = canvas.tokens?.placeables?.find(eintrag => eintrag.id === daten.targetTokenId);
            if (token?.actor) return token.actor;
        }

        if (daten.targetTokenUuid) {
            try {
                const dokument = await fromUuid(daten.targetTokenUuid);
                if (dokument?.actor) return dokument.actor;
            } catch {}
        }

        if (daten.targetActorUuid) {
            try {
                const dokument = await fromUuid(daten.targetActorUuid);
                return dokument?.documentName === "Token" ? dokument.actor : dokument || null;
            } catch {}
        }

        return null;
    };

    // +++ 5 - TABELLENERGEBNISSE ++++++++++++++++++++++++++++++
    const ermittleErgebnis = wert => {
        if (wert <= -7) return {
            wurfText: "−7 oder weniger",
            wiederholen: true,
            text: "Noch einmal auf die Tabelle mit derselben Modifikation würfeln.",
            auswirkung: `Der anschließend ermittelte Effekt bleibt permanent und kann nur durch Nurtis Ahnengabe <b>Milch der Reinigung</b> mit mindestens 3 QS beseitigt werden.`,
            changes: []
        };

        if (wert <= 0) return {
            wurfText: "−6 bis 0",
            dauerFormel: "2d6",
            dauerEinheit: "Tage",
            text: "Auf der Haut des Kranken wachsen überall kleine graue Pilze, die einen harnartigen Geruch absondern und Schmerzen verursachen.",
            auswirkung: "<b>Betteln, Umschmeicheln und Verbergen −5</b> sowie <b>1 Stufe Schmerz</b>.",
            changes: [
                { key: "system.skillModifiers.FW", mode: 0, value: "Betteln -5" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Umschmeicheln -5" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Verbergen -5" },
                { key: "system.status.inpain", mode: 2, value: "1" }
            ]
        };

        if (wert <= 3) return {
            wurfText: "1 bis 3",
            dauerFormel: "2d6 + 3",
            dauerEinheit: "Stunden",
            text: "Der Kranke bekommt schlecht Luft und muss dauernd husten, wobei er stets Sporen aushustet.",
            auswirkung: "<b>Belastung −2</b> und aufgrund des Hustens <b>Verbergen −8</b>.",
            changes: [
                { key: "system.status.encumbered", mode: 2, value: "2" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Verbergen -8" }
            ]
        };

        if (wert <= 6) return {
            wurfText: "4 bis 6",
            dauerFormel: "2d6",
            dauerEinheit: "Stunden",
            text: "Der Kranke sieht seltsame Farben und hört Geräusche, die nicht da sind.",
            auswirkung: "<b>2 Stufen Betäubung</b> und <b>Sinnesschärfe −8</b>.",
            changes: [
                { key: "system.status.stunned", mode: 2, value: "2" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Sinnesschärfe -8" }
            ]
        };

        if (wert <= 9) return {
            wurfText: "7 bis 9",
            dauer: "Bis nach der übernächsten Ruhephase",
            text: "Der Kranke führt ständig leise Selbstgespräche, wobei er seine Gedanken ausspricht.",
            auswirkung: "<b>Alle Gesellschaftsfertigkeiten −6</b>.",
            changes: [
                { key: "system.skillModifiers.FW", mode: 0, value: "Betteln -6" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Durchschauen -6" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Einschüchtern -6" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Umschmeicheln -6" }
            ]
        };

        if (wert === 10) return {
            wurfText: "10",
            dauer: "Keine",
            text: "Der Schwammkönig scheint es gut mit dem Erwachten zu meinen …",
            auswirkung: "<b>Keine Auswirkung.</b>",
            changes: [],
            keinEffekt: true
        };

        if (wert <= 13) return {
            wurfText: "11 bis 13",
            dauer: "Bis nach der übernächsten Ruhephase",
            text: "Haut und Augen des Kranken verfärben sich grau und der Kranke ist schläfrig.",
            auswirkung: `<b>1 Stufe Betäubung.</b> In jedem ruhigen Augenblick oder jede Stunde muss der Kranke eine Probe auf <b>Selbstbeherrschung</b> ablegen, sonst schläft er ein.`,
            changes: [
                { key: "system.status.stunned", mode: 2, value: "1" }
            ]
        };

        if (wert <= 16) return {
            wurfText: "14 bis 16",
            dauer: "Bis zur übernächsten Ruhephase",
            text: "Der Kranke nimmt seine gesamte Umwelt unheimlich intensiv wahr und hat unglaublich geschärfte Sinne.",
            auswirkung: "<b>Sinnesschärfe +6</b> sowie <b>Selbstbeherrschung und Willenskraft −2</b>.",
            changes: [
                { key: "system.skillModifiers.FW", mode: 0, value: "Sinnesschärfe +6" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Selbstbeherrschung -2" },
                { key: "system.skillModifiers.FW", mode: 0, value: "Willenskraft -2" }
            ]
        };

        if (wert <= 19) return {
            wurfText: "17 bis 19",
            dauer: "Bis nach der nächsten Ruhephase",
            text: "Der Kranke fühlt sich ein wenig benebelt.",
            auswirkung: "<b>1 Stufe Betäubung.</b>",
            changes: [
                { key: "system.status.stunned", mode: 2, value: "1" }
            ]
        };

        if (wert <= 22) return {
            wurfText: "20 bis 22",
            dauer: "2 Stunden",
            text: "Dem Kranken ist zwar für 2 Stunden ein wenig übel und er hat überschwänglich gute Laune, aber mehr auch nicht.",
            auswirkung: "",
            changes: [],
            keinEffekt: true
        };

        return {
            wurfText: "23 oder mehr",
            dauer: "Bis nach der nächsten Ruhephase",
            text: "Der Kranke fühlt sich gestärkt und ist voller Selbstvertrauen.",
            auswirkung: "<b>1 Stufe Selbstvertrauen.</b>",
            changes: [
                { key: "system.status.selfconfidence", mode: 2, value: "1" }
            ]
        };
    };

    // +++ 6 - PILZKRANKHEIT ÜBER BLOCK 6 ANWENDEN +++++++++++++
const wendePilzkrankheitAn = async daten => {
    const targetActor = await ladeZielActor(daten);

    if (!targetActor) {
        ui.notifications.warn(
            "Luna sagt 🌙: Das Ziel der Pilzkrankheit wurde nicht gefunden!"
        );
        return false;
    }

    if (daten.keinEffekt) return true;

    // Vorhandene Pilzkrankheit ersetzen.
    const altePilzkrankheiten = targetActor.effects.filter(effect =>
        (effect.name || effect.label || "") === EFFEKT_NAME &&
        effect.getFlag("dsk", "pilzkrankheit") === true
    );

    if (altePilzkrankheiten.length) {
        await targetActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            altePilzkrankheiten.map(effect => effect.id)
        );
    }

    const beschreibung =
        `${daten.text}` +
        `${daten.auswirkung ? `<br><br>${daten.auswirkung}` : ""}` +
        `<br><br><b>Wurf:</b> ${daten.wurfText}` +
        `<br><b>Wirkungsdauer:</b> ${daten.dauer}`;

    // Bewährte Effektanlage vollständig über Block 6.
    const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
        name: EFFEKT_NAME,
        beschreibung,
        gabeZiel: "erwachte",
        qs: 1,
        ziel: targetActor,
        changes: foundry.utils.deepClone(daten.changes || []),
        duration: daten.dauerSekunden
            ? {
                seconds: daten.dauerSekunden,
                startTime: game.time.worldTime
            }
            : null,
        showIcon: 1,
        type: "base",
        flags: {
            dsk: {
                pilzkrankheit: true,
                casterUuid: daten.casterUuid,
                casterName: daten.casterName,
                wurfText: daten.wurfText,
                permanent: Boolean(daten.permanent),
                widerstand: daten.widerstand,
                widerstandswert: daten.widerstandsWert,
                pilzmodifikator: daten.pilzmodifikator
            }
        }
    });

    if (!erzeugterEffekt) return false;

    // Sonderfall Pilzkrankheit:
    // Nur das Bild wird nach der bewährten Effektanlage lokal ersetzt.
    try {
        await erzeugterEffekt.update({
            img: PILZ_BILD,
            icon: PILZ_BILD,
            showIcon: 1
        });
    } catch (error) {
        console.error(
            "Pilzkrankheit: Das Pilzbild konnte nicht gesetzt werden.",
            {
                effekt: erzeugterEffekt,
                effektUuid: erzeugterEffekt.uuid,
                pilzBild: PILZ_BILD,
                error
            }
        );

        // Kein halbfertiger Effekt bestehen lassen.
        try {
            await erzeugterEffekt.delete();
        } catch {}

        return false;
    }

    // Tatsächliche Effektdaten kontrollieren.
    const aktualisierterEffekt =
        targetActor.effects.get(erzeugterEffekt.id) ||
        erzeugterEffekt;

    const effektNameKorrekt =
        (aktualisierterEffekt.name ||
            aktualisierterEffekt.label ||
            "") === EFFEKT_NAME;

    const effektFlagKorrekt =
        aktualisierterEffekt.getFlag(
            "dsk",
            "pilzkrankheit"
        ) === true;

    const effektBildKorrekt =
        String(
            aktualisierterEffekt.img ||
            aktualisierterEffekt.icon ||
            ""
        ) === PILZ_BILD;

    const iconSichtbar =
        Number(
            aktualisierterEffekt.showIcon
        ) === 1;

    if (
        !effektNameKorrekt ||
        !effektFlagKorrekt ||
        !effektBildKorrekt ||
        !iconSichtbar
    ) {
        console.error(
            "Pilzkrankheit: Der erzeugte Effekt ist unvollständig.",
            {
                effektNameKorrekt,
                effektFlagKorrekt,
                effektBildKorrekt,
                iconSichtbar,
                name:
                    aktualisierterEffekt.name ||
                    aktualisierterEffekt.label,
                img: aktualisierterEffekt.img,
                icon: aktualisierterEffekt.icon,
                showIcon:
                    aktualisierterEffekt.showIcon
            }
        );

        try {
            await aktualisierterEffekt.delete();
        } catch {}

        return false;
    }

    return true;
};

    // +++ 7 - GEMEINSAME KARTE IM GABENLAYOUT +++++++++++++++++
    const kartenInhalt = (daten, { gmLink = "", gmBereich = false, angewendet = false } = {}) => {
        const modText = daten.pilzmodifikator >= 0
            ? `+${daten.pilzmodifikator}`
            : String(daten.pilzmodifikator);

        const beschreibung = `
            <p><b>Unverrechneter W20:</b> ${daten.rohWurf}</p>
            <p><b>Verwendeter Widerstand:</b> ${daten.widerstandsName} ${daten.widerstandsWert}</p>
            <p><b>Pilzkrankheits-Modifikator:</b> ${modText}</p>
            <p><b>Berechnung:</b> ${daten.rohWurf} ${vorzeichen(daten.pilzmodifikator)} − ${daten.widerstandsWert} = ${daten.endwert}</p>
        `;

        const permanentHtml = daten.permanent ? `
            <p style="text-align:center;color:#B30000;font-weight:bold;margin:8px 0;">
                Der endgültig ermittelte Effekt ist permanent.
            </p>
        ` : "";

        const gmHtml = gmBereich && !angewendet && !daten.keinEffekt ? `
            <section class="secret">
                <hr>
                <div style="text-align:center;">
                    <p style="margin:0 0 6px;color:#76301b;font-weight:bold;">
                        Gabenwirkung Information (Nur SL)
                    </p>
                    <p style="margin:0 0 6px;font-size:.82em;color:#555;">
                        Es ist keine erneute Target-Auswahl nötig.
                    </p>
                    <div style="display:flex;justify-content:center;margin-top:6px;">
                        ${gmLink}
                    </div>
                </div>
            </section>
        ` : "";

        return `
            <div style="font-family:'Signika',sans-serif;">
                ${kopf("Pilzkrankheit")}

                <div class="dskbox2" style="margin-top:10px;">
                    ${DSK_FW.GabenUI.Details({
                        titel: "Pilzkrankheit Information",
                        inhalt: beschreibung
                    })}

                    <hr>

                    <p style="margin:0 0 4px;text-align:left;"><b>Würfelnder:</b></p>
                    ${DSK_FW.UI.List([daten.casterName])}

                    <p style="margin:8px 0 4px;text-align:left;"><b>Betroffenes Ziel:</b></p>
                    ${DSK_FW.UI.List([daten.targetName])}

                    <hr>

                    <p style="text-align:center;color:#76301b;font-weight:bold;margin:8px 0;">
                        Wurf: ${daten.wurfText}
                    </p>

                    ${permanentHtml}

                    <p>${daten.text}</p>
                    ${daten.auswirkung ? `<p>${daten.auswirkung}</p>` : ""}

                    <hr>

                    <p style="text-align:center;margin-bottom:0;">
                        <b>Wirkungsdauer:</b> ${daten.dauer}
                    </p>

                    ${gmHtml}
                </div>
            </div>
        `;
    };

    // +++ 8 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++
    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !istAktiverGM()) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum würfelnden Akteur.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const verarbeitet = await wendePilzkrankheitAn(daten);

        if (!verarbeitet) {
            ui.notifications.error(`Luna sagt 🌙: Pilzkrankheit konnte auf ${daten.targetName} nicht angewendet werden!`);
            return false;
        }

        const message = game.messages.get(daten.messageId);

        if (message) {
            await message.update({
                content: kartenInhalt(daten, {
                    gmBereich: false,
                    angewendet: true
                }),
                "flags.dsk.angewendet": true
            });
        }

        return true;
    };

    // +++ 9 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++
    if (game.user.isGM) {
        const offeneAnfragen = DSK_FW.GMAnfrage.Finden(FLAG_KEY);

        if (offeneAnfragen.length) {
            for (const anfrageActor of offeneAnfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, FLAG_KEY);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, FLAG_KEY);
                }
            }

            return;
        }
    }

    // +++ 10 - WÜRFELNDEN AKTEUR ERMITTELN ++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor).find(actor => actor?.isOwner) ||
            game.actors.find(actor => actor.isOwner && actor.type === "character") ||
            game.actors.find(actor => actor.isOwner) ||
            null;
    }

    if (!casterActor) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen eigenen Token aus!");
    }

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für den würfelnden Akteur!");
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 11 - TARGET UND WIDERSTÄNDE +++++++++++++++++++++++++
    const targets = Array.from(game.user.targets);

    if (targets.length !== 1) {
        return ui.notifications.warn("Luna sagt 🌙: Wähle genau einen Akteur als Ziel der Pilzkrankheit aus!");
    }

    const targetToken = targets[0];
    const targetActor = targetToken?.actor;

    if (!targetActor) {
        return ui.notifications.warn("Luna sagt 🌙: Das ausgewählte Ziel besitzt keinen gültigen Akteur!");
    }

    const targetName = targetToken.name || targetActor.name || "Unbekanntes Ziel";
    const SK = Number(targetActor.system?.stats?.sk?.value);
    const ZK = Number(targetActor.system?.stats?.zk?.value);

    if (!Number.isFinite(SK) || !Number.isFinite(ZK)) {
        return ui.notifications.error(
            `Luna sagt 🌙: Seelenkraft oder Zähigkeit konnte bei ${targetName} nicht ausgelesen werden!`
        );
    }

    // +++ 12 - ABFRAGEFENSTER +++++++++++++++++++++++++++++++++
    const dialogInhalt = `
        <div style="font-family:'Signika',sans-serif;">
            ${kopf("Pilzkrankheit würfeln")}

            ${DSK_FW.UI.Box("dskbox2", `
                <p style="margin-top:0;"><b>Würfelnder:</b> ${casterName}</p>
                <p><b>Ziel:</b> ${targetName}</p>
                <hr>

                <p style="margin-bottom:5px;"><b>Erkannte Widerstände des Ziels:</b></p>

                <div style="display:flex;flex-direction:column;gap:6px;margin-bottom:10px;">
                    <label style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 9px;background:rgba(0,0,0,.05);border-radius:4px;cursor:pointer;">
                        <span style="display:flex;align-items:center;gap:7px;">
                            <input type="radio" name="widerstand" value="zk" checked>
                            <b>Zähigkeit</b>
                        </span>
                        <b>${ZK}</b>
                    </label>

                    <label style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 9px;background:rgba(0,0,0,.05);border-radius:4px;cursor:pointer;">
                        <span style="display:flex;align-items:center;gap:7px;">
                            <input type="radio" name="widerstand" value="sk">
                            <b>Seelenkraft</b>
                        </span>
                        <b>${SK}</b>
                    </label>
                </div>

                <hr>

                <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin:8px 0;">
                    <label for="pilzkrankheit-modifikator"><b>Pilzkrankheits-Modifikator:</b></label>
                    <input id="pilzkrankheit-modifikator" name="modifikator" type="number"
                        value="0" step="1" style="width:70px;text-align:center;font-weight:bold;">
                </div>

                <div style="margin:9px 0;padding:7px 9px;background:rgba(0,0,0,.05);border-radius:4px;font-size:.9em;">
                    <p style="margin:0 0 5px;"><b>Trage nur die Zahl aus der Pilzangabe ein:</b></p>
                    <p style="margin:2px 0;">Zähigkeit −1 → <b>−1</b></p>
                    <p style="margin:2px 0;">Seelenkraft −3 → <b>−3</b></p>
                    <p style="margin:2px 0;">Zähigkeit +12 → <b>+12</b></p>
                </div>

                <hr>

                <p style="text-align:center;margin-bottom:0;">
                    <b>1W20 + Pilzmodifikator − Widerstand</b>
                </p>

                <button id="dlgApply" type="button"
                    style="${DSK_FW.GabenUI.ButtonStyle()};margin-top:10px;">
                    <i class="fas fa-dice-d20"></i> Pilzkrankheit würfeln
                </button>
            `)}
        </div>
    `;

    const eingabe = await new Promise(resolve => {
        let abgeschlossen = false;

        const abschliessen = wert => {
            if (abgeschlossen) return;
            abgeschlossen = true;
            resolve(wert);
        };

        const dialog = new Dialog({
            title: `Pilzkrankheit – ${targetName}`,
            content: dialogInhalt,
            buttons: {},

            render: html => {
                const container = html instanceof jQuery ? html[0] : html;
                const button = container?.querySelector("#dlgApply");
                const input = container?.querySelector('[name="modifikator"]');

                button?.addEventListener("click", () => {
                    const widerstand = container.querySelector('[name="widerstand"]:checked')?.value;
                    const modifikator = Number(input?.value);

                    if (!["sk", "zk"].includes(widerstand)) {
                        return ui.notifications.warn("Luna sagt 🌙: Wähle Zähigkeit oder Seelenkraft aus!");
                    }

                    if (!Number.isFinite(modifikator)) {
                        return ui.notifications.warn(
                            "Luna sagt 🌙: Trage einen gültigen Pilzkrankheits-Modifikator ein!"
                        );
                    }

                    abschliessen({
                        widerstand,
                        modifikator: Math.trunc(modifikator)
                    });

                    dialog.close();
                });

                input?.addEventListener("keydown", event => {
                    if (event.key !== "Enter") return;
                    event.preventDefault();
                    button?.click();
                });

                input?.focus();
                input?.select();
            },

            close: () => abschliessen(null)
        }, {
            width: 520,
            height: "auto"
        });

        dialog.render(true);
    });

    if (!eingabe) return;

    // +++ 13 - SICHTBARE 1W20-WÜRFE +++++++++++++++++++++++++++
    const widerstandsName = eingabe.widerstand === "sk" ? "Seelenkraft" : "Zähigkeit";
    const widerstandsWert = eingabe.widerstand === "sk" ? SK : ZK;
    const pilzmodifikator = eingabe.modifikator;

    let ergebnis = null;
    let permanent = false;
    let letzterRohWurf = 0;
    let letzterEndwert = 0;

    for (let nummer = 1; nummer <= 100; nummer++) {
        const rohWurf = await new Roll("1d20").evaluate();
        letzterRohWurf = Number(rohWurf.total) || 0;
        letzterEndwert = letzterRohWurf + pilzmodifikator - widerstandsWert;

        await rohWurf.toMessage({
            speaker: ChatMessage.getSpeaker({
                actor: casterActor,
                token: casterToken?.document || null
            }),
            flavor: nummer === 1
                ? `Pilzkrankheit – unverrechneter W20 für ${targetName}`
                : `Pilzkrankheit – Wiederholungswurf für ${targetName}`
        });

        const tabellenwert = ermittleErgebnis(letzterEndwert);

        if (!tabellenwert.wiederholen) {
            ergebnis = tabellenwert;
            break;
        }

        permanent = true;
    }

    if (!ergebnis) {
        return ui.notifications.error(
            "Luna sagt 🌙: Es konnte kein endgültiges Tabellenergebnis ermittelt werden!"
        );
    }

    // +++ 14 - WIRKUNGSDAUER ++++++++++++++++++++++++++++++++++
    let dauer = permanent ? "Permanent" : ergebnis.dauer;
    let dauerSekunden = null;

    if (!permanent && ergebnis.dauerFormel) {
        const dauerWurf = await new Roll(ergebnis.dauerFormel).evaluate();

        dauer = `${dauerWurf.total} ${ergebnis.dauerEinheit}`;

        dauerSekunden = ergebnis.dauerEinheit === "Tage"
            ? dauerWurf.total * 86400
            : dauerWurf.total * 3600;
    } else if (!permanent && ergebnis.dauer === "2 Stunden") {
        dauerSekunden = 7200;
    }

    // +++ 15 - ANFRAGEDATEN +++++++++++++++++++++++++++++++++++
    const daten = {
        casterUuid: casterActor.uuid,
        casterName,
        casterTokenId: casterToken?.id || null,
        casterTokenUuid: casterToken?.document?.uuid || casterToken?.uuid || null,

        targetActorUuid: targetActor.uuid,
        targetTokenId: targetToken.id,
        targetTokenUuid: targetToken.document?.uuid || targetToken.uuid || null,
        targetName,

        widerstand: eingabe.widerstand,
        widerstandsName,
        widerstandsWert,
        pilzmodifikator,

        rohWurf: letzterRohWurf,
        endwert: letzterEndwert,
        wurfText: ergebnis.wurfText,

        text: ergebnis.text,
        auswirkung: ergebnis.auswirkung,
        changes: foundry.utils.deepClone(ergebnis.changes || []),
        keinEffekt: Boolean(ergebnis.keinEffekt),

        permanent,
        dauer,
        dauerSekunden,

        sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: null,
        macroUuid
    };

    // +++ 16 - GM DIREKT ++++++++++++++++++++++++++++++++++++++
    if (game.user.isGM) {
        await wendePilzkrankheitAn(daten);

        await ChatMessage.create({
            speaker: ChatMessage.getSpeaker({
                actor: casterActor,
                token: casterToken?.document || null
            }),
            content: kartenInhalt(daten, {
                gmBereich: false,
                angewendet: true
            }),
            flags: {
                dsk: {
                    gabenAnfrage: true,
                    gabenName: EFFEKT_NAME,
                    pilzkrankheit: true,
                    angewendet: true
                }
            }
        });

        return;
    }

    // +++ 17 - SPIELERKARTE UND GM-ANFRAGE ++++++++++++++++++++
    if (!macroUuid && !daten.keinEffekt) {
        return ui.notifications.error(
            "Luna sagt 🌙: Die Makro-UUID konnte nicht ermittelt werden. Der GM-Button kann nicht erstellt werden!"
        );
    }

    const gmLink = daten.keinEffekt
        ? ""
        : DSK_FW.GabenUI.GMMakroButton(
            macroUuid,
            "Effekt anwenden",
            "Das Makro muss durch die Spielleitung ausgeführt werden."
        );

    const nachricht = await ChatMessage.create({
        speaker: ChatMessage.getSpeaker({
            actor: casterActor,
            token: casterToken?.document || null
        }),
        content: kartenInhalt(daten, {
            gmLink,
            gmBereich: !daten.keinEffekt,
            angewendet: false
        }),
        flags: {
            dsk: {
                gabenAnfrage: true,
                gabenName: EFFEKT_NAME,
                pilzkrankheit: true,
                angewendet: Boolean(daten.keinEffekt),
                anfragenderUserId: game.user.id
            }
        }
    });

    if (!nachricht) {
        return ui.notifications.error(
            "Luna sagt 🌙: Die Pilzkrankheitskarte konnte nicht erstellt werden!"
        );
    }

    daten.messageId = nachricht.id;

    if (!daten.keinEffekt) {
        const gespeichert = await DSK_FW.GMAnfrage.Speichern(
            casterActor,
            FLAG_KEY,
            daten
        );

        if (!gespeichert) {
            return ui.notifications.error(
                "Luna sagt 🌙: Die GM-Anfrage konnte nicht gespeichert werden!"
            );
        }

        ui.notifications.info(
            "Luna sagt 🌙: Die Pilzkrankheit wurde bei der Spielleitung zur Anwendung vorgemerkt."
        );
    }

}).call(this);
